css:
/* General styles for printing */
body {
    font-family: Georgia, serif;
    margin: 0;
    padding: 0;
    color: #000;
}

/* Hide elements that shouldn't be printed */
.no-print {
    display: none !important;
}

/* Adjust header and paragraph styles for print */
h1 {
    font-size: 16px;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

p {
    font-size: 12px;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

/* Page break styles */
@page {
    size: auto;
}

@media print {

    /* Page breaks */
    .content {
        page-break-after: always;
    }

    .footer {
        position: fixed;
        bottom: 0px;
    }
}

body {
    font-family: Arial, sans-serif;
    line-height: 1.6;
}

.content {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.no-print {
    display: none;
}

.contentDate h3 {
    font-weight: 300;
}

.contentDateSpan {
    text-transform: none;
}

.flight-details {
    display: flex;
    justify-content: space-between;
}

.flight-details .left,
.flight-details .right {
    width: 45%;
}

.flight-details p {
    margin: 5px 0;
}

.gap {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.bold {
    font-weight: 600;
}

.underline {
    text-decoration: underline;
}

.FontSizeHtag {
    font-size: 15px;
}

.FontSizePtag {
    font-size: 12px;
}

.contentDateFlex {
    display: flex;
    width: 70%;
    gap: 10px;
}

.uppercase {
    text-transform: uppercase;
}

.contentDateFlexCol {
    max-width: 100%;
    min-width: fit-content;
    width: 33%;
}

.contentDateLargeSpace {
    display: flex;
    flex-direction: column;
    gap: 60px;
}

.contentDateLargeSpace2 {
    display: flex;
    flex-direction: column;
    gap: 100px;
}

.TopLine {
    border-top: 1px solid black;
}

.center {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

.Fontfamily {
    font-family: auto;
}

.alignCenter {
    text-align: center;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th,
td {
    border: 1px solid black;
    padding: 5px;
    text-align: left;
}

.header,
.address,
.body,
.footer {
    margin-bottom: 20px;
}
